import re
from collections import deque

def solve(env, goal):
    # Parse the goal to identify the item to find and the destination
    m = re.search(r"put a (.+?) in (.+?)[.!]?$", goal.strip(), re.IGNORECASE)
    if m:
        item_desc = m.group(1).strip().lower()
        dest_desc = m.group(2).strip().lower()
    else:
        # fallback: try "put ... in ..."
        parts = goal.lower().replace("put", "", 1).replace("in", "|", 1).split("|")
        item_desc = parts[0].strip(" a") if len(parts) > 0 else ""
        dest_desc = parts[1].strip(" .") if len(parts) > 1 else ""

    item_base = item_desc
    # remove trailing numbers like " 1" from descriptions for matching
    item_base_clean = re.sub(r"\s+\d+$", "", item_desc).strip()
    dest_base_clean = re.sub(r"\s+\d+$", "", dest_desc).strip()

    def norm(s):
        return re.sub(r"\s+\d+$", "", s.strip().lower())

    # Discover the environment
    env.step("look")
    obs = env.observation
    room = obs

    # parse receptacles from the initial room description
    receptacles = []
    for token in re.findall(r"\b([a-zA-Z]+(?:\s+[a-zA-Z]+)*\s+\d+)\b", room):
        t = token.strip()
        # avoid things like "drawer 6" duplicates? keep all
        if t not in receptacles:
            receptacles.append(t)

    # also include any receptacle names seen later
    def extract_receptacles(text):
        found = []
        for t in re.findall(r"\b([a-zA-Z]+(?:\s+[a-zA-Z]+)*\s+\d+)\b", text):
            t = t.strip()
            if t not in found:
                found.append(t)
        return found

    # state
    holding = None
    current_loc = None
    searched = set()
    receptacle_contents = {}
    item_locations = {}

    def parse_obs(text):
        # update contents of current location
        nonlocal current_loc
        # "You arrive at X. On the X, you see ..."
        arr = re.search(r"You arrive at (.+?)\.", text)
        if arr:
            current_loc = arr.group(1).strip()
        on = re.search(r"On the (.+?), you see (.+)\.", text)
        if on and current_loc:
            loc = on.group(1).strip()
            items_str = on.group(2)
            items = []
            for p in re.split(r",\s*|\s+and\s+", items_str):
                p = p.strip().rstrip(".")
                if p:
                    items.append(p)
            receptacle_contents[loc] = items
        # also "you see" without "On the"
        # pickup messages
        pick = re.search(r"You pick up the (.+?) from the (.+?)\.", text)
        if pick:
            item = pick.group(1).strip()
            loc = pick.group(2).strip()
            item_locations[item] = loc
            if loc in receptacle_contents and item in receptacle_contents[loc]:
                receptacle_contents[loc].remove(item)
        mv = re.search(r"You move the (.+?) to the (.+?)\.", text)
        if mv:
            item = mv.group(1).strip()
            loc = mv.group(2).strip()
            item_locations[item] = loc
            receptacle_contents.setdefault(loc, [])
            if item not in receptacle_contents[loc]:
                receptacle_contents[loc].append(item)

    # initial parse
    parse_obs(obs)

    # helper to get all known locations
    def all_locations():
        locs = list(receptacles)
        for k in list(receptacle_contents.keys()):
            if k not in locs:
                locs.append(k)
        return locs

    # Determine destination candidates matching dest_desc
    dest_candidates = [r for r in all_locations() if norm(r) == dest_base_clean or dest_base_clean in norm(r)]
    if not dest_candidates:
        dest_candidates = [r for r in all_locations() if norm(r).startswith(dest_base_clean)]
    if not dest_candidates:
        # any receptacle containing the word
        dest_candidates = [r for r in all_locations() if dest_base_clean in norm(r)]

    # item candidates: exact name or base name match
    def item_matches(name):
        n = norm(name)
        return n == item_base_clean or item_base_clean in n or n in item_base_clean

    # BFS over locations to explore and find item
    # We'll do a simple iterative exploration: go to each receptacle, look, if item found take it.
    # Prioritize destinations and unvisited areas.

    # Keep track of visited locations
    visited = set()

    def go(loc):
        nonlocal current_loc, holding
        cmd = f"go to {loc}"
        fb = env.step(cmd)
        parse_obs(fb)
        visited.add(loc)
        return fb

    def look_here():
        fb = env.step("look")
        parse_obs(fb)
        return fb

    def take(item, loc):
        nonlocal holding
        fb = env.step(f"take {item} from {loc}")
        parse_obs(fb)
        if "pick up" in fb.lower() or "take" in fb.lower():
            holding = item
        return fb

    def move(item, loc):
        fb = env.step(f"move {item} to {loc}")
        parse_obs(fb)
        if "move" in fb.lower():
            return True
        return False

    # If already holding something matching at start (unlikely)
    # Plan: explore all receptacles until found item.
    # Use a queue of locations: first destinations, then all others.
    queue = deque()
    for d in dest_candidates:
        queue.append(d)
    for r in all_locations():
        if r not in queue and r not in dest_candidates:
            queue.append(r)

    found_item = None
    found_loc = None

    # First, check if item is visible in known contents
    for loc, items in receptacle_contents.items():
        for it in items:
            if item_matches(it):
                found_item = it
                found_loc = loc
                break
        if found_item:
            break

    while not found_item and queue:
        loc = queue.popleft()
        if loc in visited:
            continue
        fb = go(loc)
        # check contents
        items = receptacle_contents.get(loc, [])
        for it in items:
            if item_matches(it):
                found_item = it
                found_loc = loc
                break
        if found_item:
            break
        # if not found, maybe need look? go already shows contents
        # but sometimes "look" needed
        if not items:
            look_here()
            items = receptacle_contents.get(loc, [])
            for it in items:
                if item_matches(it):
                    found_item = it
                    found_loc = loc
                    break

    # If not found, maybe item is in a container? We can't open containers easily, but try look messages.
    # Also consider inventory already holding
    if not found_item:
        # try checking if we already hold something
        # parse from observation
        inv = re.search(r"You are carrying (.+)\.", env.observation)
        if inv:
            carried = [x.strip() for x in re.split(r",\s*|\s+and\s+", inv.group(1)) if x.strip()]
            for c in carried:
                if item_matches(c):
                    found_item = c
                    found_loc = None
                    holding = c
                    break

    # If still not found, do exhaustive search of all locations with look
    if not found_item:
        for loc in all_locations():
            if loc in visited:
                continue
            go(loc)
            # look explicitly
            look_here()
            items = receptacle_contents.get(loc, [])
            for it in items:
                if item_matches(it):
                    found_item = it
                    found_loc = loc
                    break
            if found_item:
                break

    # If found in a location and not holding, take it
    if found_item and found_loc is not None and holding != found_item:
        # ensure we are at found_loc
        if current_loc != found_loc:
            go(found_loc)
        take(found_item, found_loc)
        # verify holding
        if "pick up" not in env.observation.lower() and "take" not in env.observation.lower():
            # try again
            take(found_item, found_loc)

    # Now move to destination
    if holding is None and found_item is not None:
        # maybe already holding? check observation
        if re.search(r"You pick up", env.observation) or re.search(r"You are carrying", env.observation):
            holding = found_item
    if holding is None:
        # fallback: try to find again by exploring, maybe item name differs
        pass

    if holding is None and found_item is None:
        # last resort: try each location, take any item matching loosely
        for loc in all_locations():
            if loc in visited and loc not in dest_candidates:
                continue
            go(loc)
            look_here()
            for it in receptacle_contents.get(loc, []):
                n = norm(it)
                if item_base_clean in n or n in item_base_clean:
                    take(it, loc)
                    holding = it
                    break
            if holding:
                break

    # Determine destination to move to
    if dest_candidates:
        dest = dest_candidates[0]
    else:
        # pick first receptacle that isn't the source
        dest = None
        for r in all_locations():
            if r != found_loc:
                dest = r
                break
        if dest is None and all_locations():
            dest = all_locations()[0]

    if holding and dest:
        # ensure at dest
        if current_loc != dest:
            go(dest)
        # move item
        move(holding, dest)
        # verify
        if "move" not in env.observation.lower():
            # try again
            move(holding, dest)

    return env.observation
